#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_N 20
#define MAX_M 20

int n, m;
char grid[MAX_N][MAX_M + 1];
int best;

// Check if clock at (cx, cy) can be seen from seat (sx, sy) within 45 degrees
// assuming forward direction is up (north).
int can_see(int sx, int sy, int cx, int cy) {
    int dx = cx - sx;
    int dy = cy - sy;
    if (dx == 0 && dy == 0) return 0; // clock cannot be on seat
    double angle = atan2((double)dy, (double)dx) * 180.0 / M_PI;
    // forward is up: angle 90 degrees. 45 degree cone: 67.5 to 112.5
    if (angle >= 67.5 && angle <= 112.5) return 1;
    return 0;
}

int covered[MAX_N][MAX_M];

void backtrack(int placed, int start_r, int start_c) {
    // Check if all covered
    int all_covered = 1;
    for (int i = 0; i < n && all_covered; i++)
        for (int j = 0; j < m && all_covered; j++)
            if (grid[i][j] == 'S' && !covered[i][j])
                all_covered = 0;
    if (all_covered) {
        if (placed < best) best = placed;
        return;
    }
    if (placed + 1 >= best) return; // prune

    // Try placing a clock at each possible position
    for (int i = start_r; i < n; i++) {
        int j_start = (i == start_r) ? start_c : 0;
        for (int j = j_start; j < m; j++) {
            if (grid[i][j] == '#') continue;
            // Place clock at (i,j)
            int newly_covered[MAX_N][MAX_M] = {0};
            int count_new = 0;
            for (int si = 0; si < n; si++) {
                for (int sj = 0; sj < m; sj++) {
                    if (grid[si][sj] == 'S' && !covered[si][sj] && can_see(si, sj, i, j)) {
                        newly_covered[si][sj] = 1;
                        count_new++;
                    }
                }
            }
            if (count_new == 0) continue; // useless clock

            // apply
            for (int si = 0; si < n; si++)
                for (int sj = 0; sj < m; sj++)
                    if (newly_covered[si][sj])
                        covered[si][sj] = 1;

            backtrack(placed + 1, i, j + 1);

            // undo
            for (int si = 0; si < n; si++)
                for (int sj = 0; sj < m; sj++)
                    if (newly_covered[si][sj])
                        covered[si][sj] = 0;
        }
    }
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < n; i++)
        scanf("%s", grid[i]);
    best = n * m; // upper bound
    backtrack(0, 0, 0);
    printf("%d\n", best);
    return 0;
}

