#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<Point> seats(k);
    for (int i = 0; i < k; i++) {
        cin >> seats[i].x >> seats[i].y;
    }

    // Perimeter points: (0,0) to (n,0), (n,0) to (n,m), (n,m) to (0,m), (0,m) to (0,0)
    double perim = 2.0 * (n + m);
    vector<pair<double, double>> intervals;

    for (auto &s : seats) {
        double x = s.x, y = s.y;
        // For each wall, compute angle range where clock can be seen.
        // Clock is seen within ±22.5 degrees from perpendicular to nearest wall.
        // We'll consider each wall as visible if the seat is within 45° of its normal.

        // Wall bottom: y=0, normal (0,1) -> angle from seat to points on bottom wall
        // Visible if angle of vector from seat to point is within 45° of upward direction.
        // We'll generate intervals along perimeter.

        // Actually: For each wall, the visible segment is where the line from seat to point
        // makes an angle <= 22.5° with the perpendicular to that wall.
        // We compute the leftmost and rightmost visible point along perimeter.

        // Bottom wall (y=0, x in [0,n]):
        if (y > 0) {
            double half_angle = 22.5 * M_PI / 180.0;
            double dy = y;
            // tan(angle) = |dx|/dy
            double max_dx = dy * tan(half_angle);
            double x1 = max(0.0, x - max_dx);
            double x2 = min((double)n, x + max_dx);
            if (x1 <= x2) {
                double p1 = x1; // perimeter position from (0,0) clockwise
                double p2 = x2;
                intervals.push_back({p1, p2});
            }
        }

        // Right wall (x=n, y in [0,m]):
        if (x < n) {
            double half_angle = 22.5 * M_PI / 180.0;
            double dx = n - x;
            double max_dy = dx * tan(half_angle);
            double y1 = max(0.0, y - max_dy);
            double y2 = min((double)m, y + max_dy);
            if (y1 <= y2) {
                double p1 = n + y1;
                double p2 = n + y2;
                intervals.push_back({p1, p2});
            }
        }

        // Top wall (y=m, x from n down to 0):
        if (y < m) {
            double half_angle = 22.5 * M_PI / 180.0;
            double dy = m - y;
            double max_dx = dy * tan(half_angle);
            double x1 = max(0.0, x - max_dx);
            double x2 = min((double)n, x + max_dx);
            if (x1 <= x2) {
                double p1 = n + m + (n - x2);
                double p2 = n + m + (n - x1);
                intervals.push_back({p1, p2});
            }
        }

        // Left wall (x=0, y from m down to 0):
        if (x > 0) {
            double half_angle = 22.5 * M_PI / 180.0;
            double dx = x;
            double max_dy = dx * tan(half_angle);
            double y1 = max(0.0, y - max_dy);
            double y2 = min((double)m, y + max_dy);
            if (y1 <= y2) {
                double p1 = n + m + n + (m - y2);
                double p2 = n + m + n + (m - y1);
                intervals.push_back({p1, p2});
            }
        }
    }

    // Now we have intervals on a circle of length perim.
    // Duplicate intervals for circular handling.
    int sz = intervals.size();
    vector<pair<double, double>> dup;
    for (auto &inv : intervals) {
        dup.push_back({inv.first, inv.second});
        dup.push_back({inv.first + perim, inv.second + perim});
    }

    // Greedy minimum points covering: sort by right endpoint
    sort(dup.begin(), dup.end(), [](auto &a, auto &b) {
        return a.second < b.second;
    });

    int ans = 1e9;
    for (int start = 0; start < sz; start++) {
        double limit = dup[start].first + perim;
        int cnt = 1;
        double last = dup[start].second;
        for (int i = start + 1; i < dup.size() && dup[i].first < limit; i++) {
            if (dup[i].first > last) {
                cnt++;
                last = dup[i].second;
            }
        }
        ans = min(ans, cnt);
    }

    cout << ans << "\n";
    return 0;
}

