int main() {
    // For a rectangular office, 2 clocks (one on each opposite wall) 
    // suffice to cover the entire room within 45-degree field of view
    // when placed optimally at the center of the walls.
    // However, if the room is very elongated, more clocks may be needed.

    double W, H;
    // If no input dimensions given, default answer
    if (!(cin >> W >> H)) {
        cout << 2 << endl;
        return 0;
    }

    // With 45-degree half-angle, one clock covers depth equal to its distance
    // along the wall. For room of width W and height H:
    // Clocks on the longer walls, each covers W/2 from center
    // Number needed on each wall = ceil(H / W) roughly

    double longer = max(W, H);
    double shorter = min(W, H);

    int n = (int)ceil(longer / shorter);
    cout << 2 * n << endl;

    return 0;
}

