int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double w, h;
    if (!(cin >> w >> h)) return 0;

    // Each clock covers a 90-degree viewing cone (45 degrees to each side),
    // so placing clocks optimally on walls/corners gives a standard result:
    // minimum clocks needed is ceil(width / height) when width >= height,
    // otherwise ceil(height / width).
    //
    // This is equivalent to ceil(max(w, h) / min(w, h)).

    double a = max(w, h);
    double b = min(w, h);

    long long ans = (long long)ceil(a / b - 1e-12);
    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class ChocolateClocks {
    static class Interval {
        double start, end;
        Interval(double s, double e) {
            start = s;
            end = e;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double W = sc.nextDouble();
        double H = sc.nextDouble();
        int N = sc.nextInt();
        double[][] employees = new double[N][2];
        for (int i = 0; i < N; i++) {
            employees[i][0] = sc.nextDouble();
            employees[i][1] = sc.nextDouble();
        }
        sc.close();

        List<Interval> intervals = new ArrayList<>();
        double halfDiag = Math.sqrt(W * W + H * H) / 2.0;
        double angleOffset = 22.5; // half of 45 degrees

        for (int i = 0; i < N; i++) {
            double x = employees[i][0];
            double y = employees[i][1];
            // Calculate angle to each corner
            double[] angles = new double[4];
            angles[0] = Math.toDegrees(Math.atan2(H - y, -x));          // top-left
            angles[1] = Math.toDegrees(Math.atan2(H - y, W - x));       // top-right
            angles[2] = Math.toDegrees(Math.atan2(-y, W - x));          // bottom-right
            angles[3] = Math.toDegrees(Math.atan2(-y, -x));             // bottom-left
            for (int j = 0; j < 4; j++) {
                if (angles[j] < 0) angles[j] += 360;
            }
            Arrays.sort(angles);
            // The visible range is the largest gap between consecutive angles (including wrap-around)
            double maxGap = 0;
            double gapStart = 0;
            for (int j = 0; j < 4; j++) {
                double gap = angles[(j + 1) % 4] - angles[j];
                if (j == 3) gap += 360;
                if (gap > maxGap) {
                    maxGap = gap;
                    gapStart = angles[(j + 1) % 4];
                }
            }
            double visibleStart = gapStart;
            double visibleEnd = gapStart + maxGap;
            // Now restrict to 45 degrees
            double midAngle = (visibleStart + visibleEnd) / 2.0;
            double rangeStart = midAngle - angleOffset;
            double rangeEnd = midAngle + angleOffset;
            // Normalize to [0, 360)
            if (rangeStart < 0) {
                intervals.add(new Interval(rangeStart + 360, 360));
                intervals.add(new Interval(0, rangeEnd));
            } else if (rangeEnd > 360) {
                intervals.add(new Interval(rangeStart, 360));
                intervals.add(new Interval(0, rangeEnd - 360));
            } else {
                intervals.add(new Interval(rangeStart, rangeEnd));
            }
        }

        // Duplicate intervals shifted by 360 for circle unwrapping
        List<Interval> extended = new ArrayList<>();
        for (Interval iv : intervals) {
            extended.add(new Interval(iv.start, iv.end));
            extended.add(new Interval(iv.start + 360, iv.end + 360));
        }

        // Sort by end point
        extended.sort(Comparator.comparingDouble(a -> a.end));

        // Greedy covering
        int count = 0;
        double lastPoint = -1e9;
        for (Interval iv : extended) {
            if (iv.start > lastPoint + 1e-9) {
                count++;
                lastPoint = iv.end;
            }
        }

        System.out.println(count);
    }
}

